#!/usr/bin/env bash
# Deploys the staging (homologation) environment. Never touches production.
# Needs Cloudflare credentials (CLOUDFLARE_API_TOKEN, or `wrangler login`) and, on first run,
# the files generated by scripts/staging-credentials.mjs in apps/api/.staging/.
set -euo pipefail
cd "$(dirname "$0")/.."

if [ ! -f .staging/seed.sql ] || [ ! -f .staging/access-key.txt ]; then
  node scripts/staging-credentials.mjs
fi

echo "==> Building the web app"
pnpm --filter @bandsync/web build

echo "==> Deploying Worker bandsync-staging (D1 and R2 are provisioned automatically)"
npx wrangler deploy --env staging

echo "==> Applying D1 migrations to bandsync-staging"
npx wrangler d1 migrations apply bandsync-staging --remote --env staging

echo "==> Setting the staging access key secret"
tr -d '\n' < .staging/access-key.txt | npx wrangler secret put STAGING_ACCESS_KEY --env staging

echo "==> Loading fictional demo data with staging-only passwords"
npx wrangler d1 execute bandsync-staging --remote --env staging --file .staging/seed.sql --yes

echo "==> Done. Credentials are in apps/api/.staging/credentials.txt"
